let language = 'zh-Hant';
try { const saved = localStorage.getItem('folio-language'); if (Object.hasOwn(translations, saved)) language = saved; } catch {}
function t(key, values = {}) {
  const text = translations[language][key] ?? translations['zh-Hant'][key] ?? key;
  return text.replace(/\{(\w+)\}/g, (_, name) => String(values[name] ?? `{${name}}`));
}
function locale() { return language === 'zh-Hant' ? 'zh-TW' : language === 'ja' ? 'ja-JP' : 'en-US'; }
const categoryKeys = {'文學小說':'fiction','心理勵志':'psychology','歷史人文':'history','商業管理':'business','藝術設計':'design','科學新知':'science'};
function categoryName(value) { return categoryKeys[value] ? t(categoryKeys[value]) : value; }
function updateChrome() {
  document.documentElement.lang = language;
  document.title = t('appTitle');
  document.querySelectorAll('[data-i18n]').forEach(el => { el.textContent = t(el.dataset.i18n); });
  document.querySelector('#language').value = language;
  document.querySelector('#language').setAttribute('aria-label', t('language'));
}
function changeLanguage(value) {
  if (!Object.hasOwn(translations, value)) return;
  language = value;
  try { localStorage.setItem('folio-language', language); } catch {}
  updateChrome();
  render();
}
